window.products.push({"id":246005,"name":"Glass Cube Connectors for 3/16\" Thick Glass - 2 Way Glass Cubby Display Joiner - Chrome - 2 Pack","category":"homeandappliances","retail price":10.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/51yv5nkDSeL._AC_SL1000_.jpg","description":"Use our 2-way glass connectors to assemble & connect 3/16\" tempered glass cubes or cubbies. Our glass connectors are made out of a heavy duty, durable metal and come in a chrome finish. Simply insert your 3/16\" thick glass into the slot and use a flathead screw driver to tighten the connector onto the tempered glass. The screws are made out of sturdy, non marring plastic that are strong enough to hold your tempered glass together, but will not scratch the glass. Two 2-way connectors are included. We also have 3-way and 4-way connectors available. No glass cube displays are included.","images":["https://m.media-amazon.com/images/I/51yv5nkDSeL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"STORE FIXTURES DIRECT","source_asin":"B07BWG2GB7","category_path":"Home & Kitchen"},"sku":"BM-246005","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07BWG2GB7","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07BWG2GB7","price_pending":true,"merchant_ready":false});
